# cc-P760 (generated by make_shots.py): opens the Rangers' League store and asks for shots of the window and its confirm step.
import API

SIG = r"D:/UO/golems/Iron/p760-proof/guild-signal.txt"
LOG = r"D:/UO/golems/Iron/p760-proof/guild.log"


def note(text):
    with open(LOG, "a") as f:
        f.write(text + "\n")
    API.SysMsg("P760: " + text)


def shot(name):
    with open(SIG, "a") as f:
        f.write("SHOT " + name + "\n")
    API.Pause(2)


API.Pause(4)
note("opening the Rangers' League store with: guild store")
API.Msg("guild store")
API.Pause(4)
shot("guild-window")
API.ReplyGump(202)
API.Pause(4)
shot("guild-confirm")
if False:
    API.ReplyGump(1)
    API.Pause(4)
    shot("guild-after-buy")
note("done")
with open(SIG, "a") as f:
    f.write("DONE\n")
